// OrderPlaced event emitted by Order Context; consumed by Inventory & Billing
syntax = "proto3";
package ecommerce.orders.v1;

message OrderPlacedEvent {
  string order_id = 1;
  string customer_id = 2;
  repeated OrderLineItem items = 3;
  double total_amount = 4;
  int64 placed_at_unix = 5;
}
